import React from 'react';
import { CityGraph, TrafficLevel } from '../types';

interface Props {
  graph: CityGraph;
  highlightPath: string[];
}

const trafficColors: Record<TrafficLevel, string> = {
  Low: '#22c55e',
  Moderate: '#eab308',
  Heavy: '#ef4444',
  Blocked: '#94a3b8',
};

const GraphVisualization: React.FC<Props> = ({ graph, highlightPath }) => {
  const getNodeColor = (type: string) => {
    switch(type) {
      case 'Ambulance': return '#3b82f6';
      case 'Patient': return '#eab308';
      case 'Hospital': return '#22c55e';
      default: return '#64748b';
    }
  };

  const isEdgeInPath = (from: string, to: string) => {
    for (let i = 0; i < highlightPath.length - 1; i++) {
      if (
        (highlightPath[i] === from && highlightPath[i + 1] === to) ||
        (highlightPath[i] === to && highlightPath[i + 1] === from)
      ) {
        return true;
      }
    }
    return false;
  };

  return (
    <svg width="100%" height="400" viewBox="0 0 1000 600" style={{ background: '#ffffff', borderRadius: '12px', border: '2px solid #cbd5e1', boxShadow: '0 2px 8px rgba(0,0,0,0.08)' }}>
      {/* Edges */}
      {graph.edges.map((edge, idx) => {
        const fromNode = graph.nodes.find(n => n.id === edge.from)!;
        const toNode = graph.nodes.find(n => n.id === edge.to)!;
        const inPath = isEdgeInPath(edge.from, edge.to);

        return (
          <line
            key={idx}
            x1={fromNode.x}
            y1={fromNode.y}
            x2={toNode.x}
            y2={toNode.y}
            stroke={inPath ? '#2563eb' : trafficColors[edge.traffic]}
            strokeWidth={inPath ? 5 : 3}
            strokeDasharray={edge.traffic === 'Blocked' ? '8,8' : '0'}
            strokeLinecap="round"
            opacity={inPath ? 1 : 0.7}
          />
        );
      })}
      {/* Nodes */}
      {graph.nodes.map(node => (
        <g key={node.id}>
          <circle
            cx={node.x}
            cy={node.y}
            r={28}
            fill={getNodeColor(node.type)}
            stroke="white"
            strokeWidth="3"
            style={{ filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.15))' }}
          />
          <text x={node.x} y={node.y + 6} textAnchor="middle" fill="white" fontSize="16" fontWeight="700" fontFamily="Inter" style={{ textShadow: '0 1px 2px rgba(0,0,0,0.3)' }}>
            {node.id}
          </text>
          <text x={node.x} y={node.y + 48} textAnchor="middle" fill="#475569" fontSize="13" fontWeight="600" fontFamily="Inter">
            {node.name}
          </text>
        </g>
      ))}
      {/* Legend */}
      <g transform="translate(20, 20)">
        <rect x="0" y="0" width="140" height="115" fill="white" rx="8" stroke="#cbd5e1" strokeWidth="2" />
        <text x="14" y="24" fontSize="12" fontWeight="700" fill="#1e293b">Node Types</text>
        <circle cx="20" cy="45" r="8" fill="#3b82f6" />
        <text x="36" y="49" fontSize="11" fill="#475569" fontWeight="500">Start</text>
        <circle cx="20" cy="67" r="8" fill="#eab308" />
        <text x="36" y="71" fontSize="11" fill="#475569" fontWeight="500">Patient</text>
        <circle cx="20" cy="89" r="8" fill="#22c55e" />
        <text x="36" y="93" fontSize="11" fill="#475569" fontWeight="500">Hospital</text>
        <circle cx="20" cy="111" r="8" fill="#64748b" />
        <text x="36" y="115" fontSize="11" fill="#475569" fontWeight="500">Normal</text>
      </g>
      {/* Traffic Legend */}
      <g transform="translate(840, 20)">
        <rect x="0" y="0" width="140" height="110" fill="white" rx="8" stroke="#cbd5e1" strokeWidth="2" />
        <text x="14" y="24" fontSize="12" fontWeight="700" fill="#1e293b">Traffic Levels</text>
        <line x1="16" y1="42" x2="36" y2="42" stroke="#22c55e" strokeWidth="3" strokeLinecap="round" />
        <text x="44" y="46" fontSize="11" fill="#475569" fontWeight="500">Low</text>
        <line x1="16" y1="64" x2="36" y2="64" stroke="#eab308" strokeWidth="3" strokeLinecap="round" />
        <text x="44" y="68" fontSize="11" fill="#475569" fontWeight="500">Moderate</text>
        <line x1="16" y1="86" x2="36" y2="86" stroke="#ef4444" strokeWidth="3" strokeLinecap="round" />
        <text x="44" y="90" fontSize="11" fill="#475569" fontWeight="500">Heavy</text>
        <line x1="16" y1="108" x2="36" y2="108" stroke="#94a3b8" strokeWidth="3" strokeLinecap="round" strokeDasharray="4,4" />
        <text x="44" y="112" fontSize="11" fill="#475569" fontWeight="500">Blocked</text>
      </g>
    </svg>
  );
};

export default GraphVisualization;
